import os, sys

BASE = "quarterly_unpacked"

# Map styleId -> style name from styles.xml
style_map = {}
sp = os.path.join(BASE, "word", "styles.xml")
if os.path.exists(sp):
    try:
        from defusedxml import minidom
    except Exception:
        from xml.dom import minidom
    dom = minidom.parse(sp)
    for st in dom.getElementsByTagName("w:style"):
        sid = st.getAttribute("w:styleId")
        name = ""
        for nm in st.getElementsByTagName("w:name"):
            name = nm.getAttribute("w:val")
        stype = st.getAttribute("w:type")
        style_map[sid] = (name, stype)

print("=== FILES ===")
for root, dirs, files in os.walk(BASE):
    for f in sorted(files):
        p = os.path.join(root, f)
        print(os.path.relpath(p, BASE), os.path.getsize(p))

print("=== STYLES ===")
for sid, (name, stype) in sorted(style_map.items()):
    print(f"{sid!r} -> name={name!r} type={stype!r}")

print("=== PARAGRAPHS (index | pStyle | text) ===")
dp = os.path.join(BASE, "word", "document.xml")
try:
    from defusedxml import minidom
except Exception:
    from xml.dom import minidom
dom = minidom.parse(dp)
paras = dom.getElementsByTagName("w:p")
for i, p in enumerate(paras):
    style = ""
    for pPr in p.getElementsByTagName("w:pPr"):
        for ps in pPr.getElementsByTagName("w:pStyle"):
            style = ps.getAttribute("w:val")
    text = "".join(
        t.data
        for t in p.getElementsByTagName("w:t")
    )
    if "w:delText" in p.toxml():
        text += " [contains delText]"
    print(f"{i:4d} | {style!r:12s} | {text[:90]!r}")

#!/usr/bin/env python3
"""Task-scoped helper: underline every headline paragraph in the unpacked
quarterly_report.docx intermediate (unpacked_quarterly_report/word/document.xml).

Headlines are the report's section headings. This document defines them purely
by their text runs (there is no w:pStyle markup): a headline paragraph is one
whose combined visible text is non-empty, contains at least one letter, and has
no lowercase letters (e.g. "EXECUTIVE SUMMARY", "Q1 2025 OUTLOOK"). Body prose,
bullet rows, and segment data rows all contain lowercase text and are excluded.
Underlining is applied as a run property <w:u w:val="single"/> so it renders in
Word; text content is left untouched.
"""
import os
import xml.dom.minidom as minidom

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
DOC_PATH = os.path.join("unpacked_quarterly_report", "word", "document.xml")


def para_text(p):
    """Concatenated visible text of a w:p (w:t plus any w:delText)."""
    parts = []
    for tag in ("t", "delText"):
        for node in p.getElementsByTagNameNS(W_NS, tag):
            if node.firstChild is not None:
                parts.append(node.firstChild.data)
    return "".join(parts)


def is_headline(text):
    """True when the paragraph text looks like an all-caps section headline."""
    s = text.strip()
    if not s:
        return False
    if not any(ch.isalpha() for ch in s):
        return False
    return not any(ch.islower() for ch in s)


def underline_runs(p, dom):
    """Add <w:u w:val='single'/> to each run's rPr in paragraph p.

    Element order inside rPr is schema-sensitive; these runs carry only
    rFonts/sz/sz-cs (all of which precede w:u), so appending keeps valid order.
    """
    rprs = p.getElementsByTagNameNS(W_NS, "rPr")
    if rprs:
        rpr = rprs[0]
    else:
        rpr = dom.createElementNS(W_NS, "w:rPr")
        p.insertBefore(rpr, p.firstChild)
    if rpr.getElementsByTagNameNS(W_NS, "u"):
        return 0
    u = dom.createElementNS(W_NS, "w:u")
    u.setAttributeNS(None, "w:val", "single")
    hl = rpr.getElementsByTagNameNS(W_NS, "highlight")
    if hl:
        rpr.insertBefore(u, hl[0])
    else:
        rpr.appendChild(u)
    return 1


def main():
    dom = minidom.parse(DOC_PATH)
    edited = []
    for p in dom.getElementsByTagNameNS(W_NS, "p"):
        text = para_text(p)
        if not is_headline(text):
            continue
        runs = p.getElementsByTagNameNS(W_NS, "r")
        count = sum(underline_runs(r, dom) for r in runs)
        if count:
            edited.append((count, text.strip()))

    with open(DOC_PATH, "w", encoding="utf-8") as f:
        dom.writexml(f, "", "", "", "utf-8")

    # Self-check: reload and confirm the same paragraphs are now underlined.
    dom2 = minidom.parse(DOC_PATH)
    rechecked = []
    for p in dom2.getElementsByTagNameNS(W_NS, "p"):
        text = para_text(p)
        if not is_headline(text):
            continue
        underlined = sum(
            1
            for r in p.getElementsByTagNameNS(W_NS, "r")
            if r.getElementsByTagNameNS(W_NS, "rPr")
            and r.getElementsByTagNameNS(W_NS, "rPr")[0].getElementsByTagNameNS(
                W_NS, "u"
            )
        )
        rechecked.append((underlined, text.strip()))

    print("Headline paragraphs underlined during edit: %d" % len(edited))
    for count, text in edited:
        print("  - [%d run(s)] %s" % (count, text))
    print("Recheck after reload: %d headline paragraphs with w:u" % len(rechecked))
    for count, text in rechecked:
        status = "OK" if count else "MISSING"
        print("  - [%d run(s)] %s -> %s" % (count, text, status))
    if len(rechecked) != len(edited) or any(c == 0 for c, _ in rechecked):
        raise SystemExit("Verification failed: not all headlines underlined.")


if __name__ == "__main__":
    main()

