#!/usr/bin/env python3
"""Underline all headlines in the unpacked quarterly_report.docx.

Usage: python underline_headlines.py <unpacked_dir>

Headlines in this report are short all-caps section titles (no heading
styles exist in the document). We detect them as paragraphs whose text
is non-empty, contains at least one alphabetic character, and is entirely
uppercase, then add <w:u w:val="single"/> to the run properties of the
runs carrying that text. Editing is done directly on word/document.xml
with secure parsing, preserving the file's original ASCII/entity style.
"""
import os
import sys

from defusedxml import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def paragraph_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild and t.firstChild.nodeType == t.TEXT_NODE:
            parts.append(t.firstChild.data)
    return "".join(parts)


def is_headline(text):
    stripped = text.strip()
    return bool(stripped) and any(ch.isalpha() for ch in stripped) and stripped == stripped.upper()


def underline_headlines(dom):
    body = dom.getElementsByTagName("w:body")[0]
    found = []
    for p in body.getElementsByTagName("w:p"):
        text = paragraph_text(p)
        if not is_headline(text):
            continue
        found.append(text)
        for r in p.getElementsByTagName("w:r"):
            if not r.getElementsByTagName("w:t"):
                continue
            rprs = r.getElementsByTagName("w:rPr")
            rpr = rprs[0] if rprs else None
            if rpr is None:
                rpr = dom.createElementNS(W, "w:rPr")
                r.insertBefore(rpr, r.firstChild)
            if not rpr.getElementsByTagName("w:u"):
                u = dom.createElementNS(W, "w:u")
                u.setAttribute("w:val", "single")
                rpr.appendChild(u)
    return found


def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: python underline_headlines.py <unpacked_dir>")
    unpacked = sys.argv[1]
    xml_path = os.path.join(unpacked, "word", "document.xml")
    if not os.path.isfile(xml_path):
        raise SystemExit("ERROR: document.xml not found: " + xml_path)

    dom = minidom.parse(xml_path)
    headlines = underline_headlines(dom)
    if not headlines:
        raise SystemExit("ERROR: no headlines found to underline")

    with open(xml_path, "wb") as f:
        f.write(dom.toxml(encoding="ascii"))

    # Verification pass: re-parse and confirm every headline paragraph is underlined.
    dom2 = minidom.parse(xml_path)
    body = dom2.getElementsByTagName("w:body")[0]
    underlined = []
    for p in body.getElementsByTagName("w:p"):
        text = paragraph_text(p)
        if not is_headline(text):
            continue
        runs = p.getElementsByTagName("w:r")
        all_underlined = all(
            (not r.getElementsByTagName("w:t")) or r.getElementsByTagName("w:u")
            for r in runs
        )
        underlined.append((text, all_underlined))
    missing = [t for t, ok in underlined if not ok]
    if len(underlined) != len(headlines) or missing:
        raise SystemExit(
            "ERROR: verification failed; missing underline on: " + ", ".join(missing)
        )
    print("Underlined {} headline(s):".format(len(headlines)))
    for h in headlines:
        print(" - " + h)


if __name__ == "__main__":
    main()
